// Shared same-origin bytes for pond host + iframe. Installed only by pond static builds.
// Authority: Will's 2026-10-04 Pages brief, "Serve each asset from one route, fetched once."
(() => {
  const budget = 120000000;
  const nativeFetch = globalThis.fetch.bind(globalThis);
  const hash = async bytes => [...new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))]
    .map(byte => byte.toString(16).padStart(2, '0')).join('');
  const matches = async (bytes, receipt) => bytes.byteLength === receipt.byte_count && await hash(bytes) === receipt.sha256;
  const declared = (catalogue, path) => Object.entries(catalogue || {})
    .find(([suffix]) => path.endsWith('/' + suffix));
  let owner = globalThis;
  try { if (parent !== globalThis && parent.location.origin === location.origin) owner = parent; } catch {}
  if (!owner.__farmPondResources) {
    const entries = new Map();
    let heldBytes = 0;
    owner.__farmPondResources = {
      stats: () => ({entries: entries.size, heldBytes, budget}),
      async read(url, options) {
        let entry = entries.get(url);
        if (!entry) {
          entry = (async () => {
            const path = new URL(url).pathname;
            const transport = typeof DecompressionStream === 'function'
              ? declared(globalThis.FARM_POND_TRANSPORT, path) : null;
            const request = transport ? url.slice(0, -transport[0].length) + transport[1].path : url;
            const response = await nativeFetch(request, options);
            if (!response.ok) throw new Error(`Pond resource HTTP ${response.status}: ${url}`);
            let bytes = await response.arrayBuffer();
            const headers = new Headers(response.headers);
            if (transport) {
              const row = transport[1];
              // HTTP servers may already decode a Content-Encoding gzip sibling.
              // Either way DT receives the exact retained source bytes and still
              // performs its own canonical receipts/static-package verification.
              if (!await matches(bytes, row.source)) {
                if (!await matches(bytes, row.transport)) throw new Error(`Pond transport receipt mismatch: ${url} (Will, 2026-10-08: fix first visit; preserve lineage)`);
                bytes = await new Response(new Response(bytes).body.pipeThrough(new DecompressionStream(row.encoding))).arrayBuffer();
                if (!await matches(bytes, row.source)) throw new Error(`Pond decoded source receipt mismatch: ${url} (Will, 2026-10-08: preserve canonical authority)`);
              }
              headers.delete('Content-Encoding');
              headers.set('Content-Length', String(bytes.byteLength));
              headers.set('Content-Type', path.endsWith('.json') ? 'application/json'
                : path.endsWith('.glb') ? 'model/gltf-binary' : 'application/octet-stream');
            }
            const expected = declared(globalThis.FARM_POND_ASSET_HASHES, path)?.[1];
            if (expected) {
              if (!await matches(bytes, expected)) {
                throw new Error(`Pond shipped asset receipt mismatch: ${url} (Will, 2026-10-04: preserve provenance)`);
              }
            }
            if (heldBytes + bytes.byteLength > budget) throw new Error('Pond resource cache exceeds 120 MB (Will, 2026-10-04: workshop cold-transfer budget)');
            heldBytes += bytes.byteLength;
            // The read-only DT loader walks file receipts serially. Overlap the
            // same selected candidate's reads, then let DT verify each exact
            // response normally. Never select or manufacture another story.
            if (/\/yilan-pond-[^/]*canonical\/manifest\.json$/.test(path)) {
              const manifest = JSON.parse(new TextDecoder().decode(bytes));
              if (Array.isArray(manifest.files) && manifest.adapter_entry) {
                const base = new URL('.', url);
                const urls = manifest.files.map(row => {
                  const target = typeof row.path === 'string' && new URL(row.path, base);
                  return target && target.origin === base.origin && target.pathname.startsWith(base.pathname)
                    && !target.search && !target.hash ? target.href : null;
                }).filter(Boolean);
                let next = 0;
                const consume = async () => {
                  while (next < urls.length) {
                    const target = urls[next++];
                    try { await owner.__farmPondResources.read(target); } catch { /* DT reports failures at its receipt boundary. */ }
                  }
                };
                for (let i = 0; i < Math.min(8, urls.length); i++) void consume();
              }
            }
            return {bytes, status: response.status, headers: [...headers]};
          })().catch(error => { entries.delete(url); throw error; });
          entries.set(url, entry);
        }
        const result = await entry;
        return new Response(result.bytes, {status: result.status, headers: result.headers});
      },
    };
  }
  globalThis.fetch = (input, options) => {
    const url = new URL(typeof input === 'string' || input instanceof URL ? input : input.url, location.href);
    const method = options?.method || input?.method || 'GET';
    if (method !== 'GET' || url.origin !== location.origin || !/\/data\/yilan-pond-[^/]+\//.test(url.pathname)
        || url.search || url.hash || options?.headers || options?.signal) return nativeFetch(input, options);
    return owner.__farmPondResources.read(url.href, options);
  };
})();
